const fs = require('fs');

function solve() {
    const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
    if (input.length < 2) return;

    let K = BigInt(input[0]);
    const t = parseInt(input[1], 10);
    K--; // 0-indexed

    // Factorials up to 16!
    const F = Array(17).fill(0n);
    F[0] = 1n;
    for (let i = 1; i <= 16; i++) {
        F[i] = F[i - 1] * BigInt(i);
    }

    function count(rem, len) {
        const dp = Array(len + 1).fill(0n);
        dp[0] = F[len];
        for (const x of rem) {
            if (x < 0) return 0n;
            if (x === 0) continue;
            for (let i = len; i >= 0; i--) {
                for (let j = 1; j <= x; j++) {
                    if (i - j < 0) break;
                    dp[i] += dp[i - j] / F[j];
                }
            }
        }
        return dp[len];
    }

    gouter:
    for (let len = 1; ; len++) {
        let ret = 0n;
        const rem = Array(16).fill(t);
        outer:
        for (let i = 0; i < len; i++) {
            const start = (i === 0) ? 1 : 0;
            for (let j = start; j < 16; j++) {
                rem[j]--;
                const c = count(rem, len - 1 - i);
                if (K < c) {
                    ret = ret * 16n + BigInt(j);
                    continue outer;
                } else {
                    K -= c;
                }
                rem[j]++;
            }
            continue gouter;
        }
        console.log(ret.toString(16));
        return;
    }
}

